Object.assign(SNIP,{});PRESET_NOTES["l21"]={"Ví dụ: Tìm số lớn nhất bằng chia đôi": "Vùng sáng là đoạn [l, r] của lời gọi đang chạy. Cây lời gọi là cây nhị phân cân bằng: 15 lời gọi cho 8 phần tử, sâu 4 tầng. Mỗi lời gọi kết hợp chỉ tốn O(1) nên tổng vẫn là O(n), không nhanh hơn vòng lặp, nhưng cho thấy rõ khung chia, trị, kết hợp.", "Ví dụ: Đoạn con có tổng lớn nhất": "Ở lời gọi gốc (l = 0, r = 7, m = 3): hai nửa trả về 4 và 3, còn đoạn cắt qua giữa có trai = 4, phai = 2, tổng 6. Kết quả 6 (đoạn 4 −1 2 1). Mũi tên i quét từ m ra hai phía: mỗi tầng của cây đệ quy quét tổng cộng n ô.", "Ví dụ: Phủ bàn cờ khuyết bằng mảnh chữ L": "Lời gọi đầu đặt mảnh 1 ở tâm (ba ô quanh tâm không thuộc phần tư chứa ô khuyết). Sau đó mỗi phần tư 2 × 2 có đúng một ô đã bị chiếm và chỉ cần thêm một mảnh. Tổng cộng (16 − 1)/3 = 5 mảnh.", "Lỗi: chia đoạn sai, đệ quy không dừng": "Với đoạn hai phần tử [0, 1]: m = 0, lời gọi tong(0, −1) là đoạn rỗng mà điều kiện dừng không bắt được, và nó lại sinh tong(0, −1)… mãi. Khi chia, hai nửa phải khác rỗng và nhỏ hơn hẳn đoạn ban đầu: [l, m] và [m + 1, r] với m = (l + r) / 2."};EX_HINTS["l21"]=[["Đoạn cắt qua điểm giữa m: đi từ m sang trái, giữ tổng lớn nhất “trai”; đi từ m + 1 sang phải, giữ tổng lớn nhất “phai”. Đoạn tốt nhất cắt qua giữa có tổng trai + phai.", "Khởi tạo trai = a[m], phai = a[m + 1] (không phải 0) vì đoạn phải khác rỗng và mọi số có thể âm.", "Tổng có thể vượt 2·10⁹: dùng long long."], ["Nếu x xuất hiện nhiều hơn một nửa đoạn thì x cũng xuất hiện nhiều hơn một nửa ở nửa trái hoặc nửa phải (nếu không, tổng số lần ≤ một nửa).", "Vậy chỉ có hai ứng viên: đa số của nửa trái và đa số của nửa phải. Đếm lại từng ứng viên trên cả đoạn trong O(n).", "T(n) = 2T(n/2) + O(n) = O(n log n)."], ["Sₖ dài 2ᵏ − 1; chữ thứ k nằm đúng giữa, ở vị trí 2ᵏ⁻¹.", "p nhỏ hơn vị trí giữa: ký tự cần tìm nằm trong bản Sₖ₋₁ bên trái, vẫn ở vị trí p. p lớn hơn: nằm trong bản bên phải, ở vị trí p − 2ᵏ⁻¹.", "Mỗi lời gọi giảm k đi 1 và chỉ gọi một lần: tối đa 26 lời gọi."]];
/* ===================== BÀI 21 · Chia để trị ===================== */
/* Bài 21 · Chia để trị
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
RACE_X["race-a21"]=Object.assign(RACE_X["race-a21"]||{},{cs:["using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        long[] a = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n        long tot = a[0];\n        for (int l = 0; l < n; l++)\n        {\n            long s = 0;\n            for (int r = l; r < n; r++)\n            {\n                s += a[r];\n                tot = Math.Max(tot, s);\n            }\n        }\n        Console.WriteLine(tot);\n    }\n}", "using System;\n\nclass Program\n{\n    static long[] a;\n\n    static long Tot(int l, int r)\n    {\n        if (l == r) return a[l];\n        int m = (l + r) / 2;\n        long kq = Math.Max(Tot(l, m), Tot(m + 1, r));\n        long s = 0, trai = a[m], phai = a[m + 1];\n        for (int i = m; i >= l; i--) { s += a[i]; trai = Math.Max(trai, s); }\n        s = 0;\n        for (int i = m + 1; i <= r; i++) { s += a[i]; phai = Math.Max(phai, s); }\n        return Math.Max(kq, trai + phai);\n    }\n\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        a = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n        Console.WriteLine(Tot(0, n - 1));\n    }\n}"]});
RACE_X["race-a21"]=Object.assign(RACE_X["race-a21"]||{},{py:["n = int(input())\na = list(map(int, input().split()))\ntot = a[0]\nfor l in range(n):\n    s = 0\n    for r in range(l, n):\n        s += a[r]\n        tot = max(tot, s)\nprint(tot)", "def tot(l, r):\n    if l == r:\n        return a[l]\n    m = (l + r) // 2\n    kq = max(tot(l, m), tot(m + 1, r))\n    s, trai = 0, a[m]\n    for i in range(m, l - 1, -1):\n        s += a[i]\n        trai = max(trai, s)\n    s, phai = 0, a[m + 1]\n    for i in range(m + 1, r + 1):\n        s += a[i]\n        phai = max(phai, s)\n    return max(kq, trai + phai)\n\nn = int(input())\na = list(map(int, input().split()))\nprint(tot(0, n - 1))"]});
makeStepRace(document.getElementById("race-a21"),{variants:[{label:"Thử mọi đoạn: O(n²)",code:"#include <iostream>\n#include <algorithm>\nusing namespace std;\n\nlong long a[100000];\n\nint main() {\n    int n;\n    cin >> n;\n    for (int i = 0; i < n; i++) cin >> a[i];\n    long long tot = a[0];\n    for (int l = 0; l < n; l++) {\n        long long s = 0;\n        for (int r = l; r < n; r++) {\n            s += a[r];\n            tot = max(tot, s);\n        }\n    }\n    cout << tot << \"\\n\";\n    return 0;\n}"},{label:"Chia để trị: O(n log n)",code:"#include <iostream>\n#include <algorithm>\nusing namespace std;\n\nlong long a[100000];\n\nlong long tot(int l, int r) {\n    if (l == r) return a[l];\n    int m = (l + r) / 2;\n    long long kq = max(tot(l, m), tot(m + 1, r));\n    long long s = 0, trai = a[m], phai = a[m + 1];\n    for (int i = m; i >= l; i--) { s += a[i]; trai = max(trai, s); }\n    s = 0;\n    for (int i = m + 1; i <= r; i++) { s += a[i]; phai = max(phai, s); }\n    return max(kq, trai + phai);\n}\n\nint main() {\n    int n;\n    cin >> n;\n    for (int i = 0; i < n; i++) cin >> a[i];\n    cout << tot(0, n - 1) << \"\\n\";\n    return 0;\n}"}],gen:n=>n+"\n"+Array.from({length:n},(_,i)=>((i*7919)%201)-100).join(" "),ns:[50,100,200,400],note:"Mỗi lần n gấp đôi, cách thử mọi đoạn tốn gấp bốn; chia để trị chỉ tốn hơn gấp đôi một chút. Với n = 10⁵: khoảng 5·10⁹ bước so với khoảng 1,7·10⁶."});
const PR21=[{label:"Ví dụ: Tìm số lớn nhất bằng chia đôi",input:"",code:"#include <iostream>\n#include <algorithm>\nusing namespace std;\n\nint a[8] = {3, 9, 2, 7, 5, 1, 8, 4};\n\nint lonNhat(int l, int r) {\n    if (l == r) return a[l];\n    int m = (l + r) / 2;\n    int x = lonNhat(l, m);\n    int y = lonNhat(m + 1, r);\n    return max(x, y);\n}\n\nint main() {\n    cout << lonNhat(0, 7) << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"a",range:["l","r"]},{type:"calls"}],py:{code:"a = [3, 9, 2, 7, 5, 1, 8, 4]\n\ndef lonNhat(l, r):\n    if l == r:\n        return a[l]\n    m = (l + r) // 2\n    x = lonNhat(l, m)\n    y = lonNhat(m + 1, r)\n    return max(x, y)\n\nprint(lonNhat(0, 7))"},cs:{code:"using System;\n\nclass Program\n{\n    static int[] a = { 3, 9, 2, 7, 5, 1, 8, 4 };\n\n    static int LonNhat(int l, int r)\n    {\n        if (l == r) return a[l];\n        int m = (l + r) / 2;\n        int x = LonNhat(l, m);\n        int y = LonNhat(m + 1, r);\n        return Math.Max(x, y);\n    }\n\n    static void Main()\n    {\n        Console.WriteLine(LonNhat(0, 7));\n    }\n}"}},{label:"Ví dụ: Đoạn con có tổng lớn nhất",input:"",code:"#include <iostream>\n#include <algorithm>\nusing namespace std;\n\nlong long a[8] = {-2, 1, -3, 4, -1, 2, 1, -5};\n\nlong long tot(int l, int r) {\n    if (l == r) return a[l];\n    int m = (l + r) / 2;\n    long long kq = max(tot(l, m), tot(m + 1, r));\n    // đoạn cắt qua giữa: đuôi tốt nhất của nửa trái + đầu tốt nhất của nửa phải\n    long long s = 0, trai = a[m], phai = a[m + 1];\n    for (int i = m; i >= l; i--) {\n        s += a[i];\n        trai = max(trai, s);\n    }\n    s = 0;\n    for (int i = m + 1; i <= r; i++) {\n        s += a[i];\n        phai = max(phai, s);\n    }\n    return max(kq, trai + phai);\n}\n\nint main() {\n    cout << tot(0, 7) << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"a",ptr:["i","m"],range:["l","r"]},{type:"vars",names:["trai","phai","kq"]}],predict:[{line:22,v:"trai + phai",q:"Đoạn cắt qua điểm giữa có tổng lớn nhất là bao nhiêu?"}],py:{code:"a = [-2, 1, -3, 4, -1, 2, 1, -5]\n\ndef tot(l, r):\n    if l == r:\n        return a[l]\n    m = (l + r) // 2\n    kq = max(tot(l, m), tot(m + 1, r))\n    # đoạn cắt qua giữa: đuôi tốt nhất của nửa trái + đầu tốt nhất của nửa phải\n    s, trai = 0, a[m]\n    for i in range(m, l - 1, -1):\n        s += a[i]\n        trai = max(trai, s)\n    s, phai = 0, a[m + 1]\n    for i in range(m + 1, r + 1):\n        s += a[i]\n        phai = max(phai, s)\n    return max(kq, trai + phai)\n\nprint(tot(0, 7))",predict:[{line:17,v:"trai + phai",q:"Đoạn cắt qua điểm giữa có tổng lớn nhất là bao nhiêu?"}]},cs:{code:"using System;\n\nclass Program\n{\n    static long[] a = { -2, 1, -3, 4, -1, 2, 1, -5 };\n\n    static long Tot(int l, int r)\n    {\n        if (l == r) return a[l];\n        int m = (l + r) / 2;\n        long kq = Math.Max(Tot(l, m), Tot(m + 1, r));\n        // đoạn cắt qua giữa: đuôi tốt nhất của nửa trái + đầu tốt nhất của nửa phải\n        long s = 0, trai = a[m], phai = a[m + 1];\n        for (int i = m; i >= l; i--)\n        {\n            s += a[i];\n            trai = Math.Max(trai, s);\n        }\n        s = 0;\n        for (int i = m + 1; i <= r; i++)\n        {\n            s += a[i];\n            phai = Math.Max(phai, s);\n        }\n        return Math.Max(kq, trai + phai);\n    }\n\n    static void Main()\n    {\n        Console.WriteLine(Tot(0, 7));\n    }\n}",predict:[{line:25,v:"trai + phai",q:"Đoạn cắt qua điểm giữa có tổng lớn nhất là bao nhiêu?"}]}},{label:"Ví dụ: Phủ bàn cờ khuyết bằng mảnh chữ L",input:"",code:"#include <iostream>\nusing namespace std;\n\nint bang[4][4];   // 0: chưa phủ, -1: ô khuyết, k: mảnh L thứ k\nint dem = 0;\n\n// phủ hình vuông cạnh n, góc trên trái (r, c); ô (kr, kc) trong đó đã bị chiếm\nvoid phu(int r, int c, int n, int kr, int kc) {\n    if (n == 1) return;\n    int h = n / 2, id = ++dem;\n    for (int k = 0; k < 4; k++) {       // đặt mảnh L ở tâm\n        int r0 = r + k / 2 * h, c0 = c + k % 2 * h;\n        bool coO = kr >= r0 && kr < r0 + h && kc >= c0 && kc < c0 + h;\n        if (!coO) bang[r + h - 1 + k / 2][c + h - 1 + k % 2] = id;\n    }\n    for (int k = 0; k < 4; k++) {       // giải 4 phần tư\n        int r0 = r + k / 2 * h, c0 = c + k % 2 * h;\n        bool coO = kr >= r0 && kr < r0 + h && kc >= c0 && kc < c0 + h;\n        if (coO) phu(r0, c0, h, kr, kc);\n        else phu(r0, c0, h, r + h - 1 + k / 2, c + h - 1 + k % 2);\n    }\n}\n\nint main() {\n    bang[0][1] = -1;\n    phu(0, 0, 4, 0, 1);\n    for (int i = 0; i < 4; i++) {\n        for (int j = 0; j < 4; j++) cout << bang[i][j] << \" \";\n        cout << \"\\n\";\n    }\n    return 0;\n}",viz:[{type:"grid",of:"bang",label:"bang"},{type:"calls"}],py:{code:"bang = [[0] * 4 for _ in range(4)]   # 0: chưa phủ, -1: ô khuyết, k: mảnh L thứ k\ndem = 0\n\n# phủ hình vuông cạnh n, góc trên trái (r, c); ô (kr, kc) trong đó đã bị chiếm\ndef phu(r, c, n, kr, kc):\n    global dem\n    if n == 1:\n        return\n    h = n // 2\n    dem += 1\n    id = dem\n    for k in range(4):                  # đặt mảnh L ở tâm\n        r0, c0 = r + k // 2 * h, c + k % 2 * h\n        coO = r0 <= kr < r0 + h and c0 <= kc < c0 + h\n        if not coO:\n            bang[r + h - 1 + k // 2][c + h - 1 + k % 2] = id\n    for k in range(4):                  # giải 4 phần tư\n        r0, c0 = r + k // 2 * h, c + k % 2 * h\n        coO = r0 <= kr < r0 + h and c0 <= kc < c0 + h\n        if coO:\n            phu(r0, c0, h, kr, kc)\n        else:\n            phu(r0, c0, h, r + h - 1 + k // 2, c + h - 1 + k % 2)\n\nbang[0][1] = -1\nphu(0, 0, 4, 0, 1)\nfor hang in bang:\n    print(*hang)"},cs:{code:"using System;\n\nclass Program\n{\n    static int[][] bang = new int[4][];   // 0: chưa phủ, -1: ô khuyết, k: mảnh L thứ k\n    static int dem = 0;\n\n    // phủ hình vuông cạnh n, góc trên trái (r, c); ô (kr, kc) trong đó đã bị chiếm\n    static void Phu(int r, int c, int n, int kr, int kc)\n    {\n        if (n == 1) return;\n        int h = n / 2, id = ++dem;\n        for (int k = 0; k < 4; k++)       // đặt mảnh L ở tâm\n        {\n            int r0 = r + k / 2 * h, c0 = c + k % 2 * h;\n            bool coO = kr >= r0 && kr < r0 + h && kc >= c0 && kc < c0 + h;\n            if (!coO) bang[r + h - 1 + k / 2][c + h - 1 + k % 2] = id;\n        }\n        for (int k = 0; k < 4; k++)       // giải 4 phần tư\n        {\n            int r0 = r + k / 2 * h, c0 = c + k % 2 * h;\n            bool coO = kr >= r0 && kr < r0 + h && kc >= c0 && kc < c0 + h;\n            if (coO) Phu(r0, c0, h, kr, kc);\n            else Phu(r0, c0, h, r + h - 1 + k / 2, c + h - 1 + k % 2);\n        }\n    }\n\n    static void Main()\n    {\n        for (int i = 0; i < 4; i++) bang[i] = new int[4];\n        bang[0][1] = -1;\n        Phu(0, 0, 4, 0, 1);\n        for (int i = 0; i < 4; i++) Console.WriteLine(string.Join(\" \", bang[i]));\n    }\n}"}},{label:"Lỗi: chia đoạn sai, đệ quy không dừng",input:"",code:"#include <iostream>\nusing namespace std;\n\nint a[5] = {3, 1, 4, 1, 5};\n\nint tong(int l, int r) {          // tổng a[l..r]\n    if (l == r) return a[l];\n    int m = (l + r) / 2;\n    return tong(l, m - 1) + tong(m, r);   // sai: phải là tong(l, m) + tong(m + 1, r)\n}\n\nint main() {\n    cout << tong(0, 4) << \"\\n\";\n    return 0;\n}",py:{code:"a = [3, 1, 4, 1, 5]\n\ndef tong(l, r):          # tổng a[l..r]\n    if l == r:\n        return a[l]\n    m = (l + r) // 2\n    return tong(l, m - 1) + tong(m, r)   # sai: phải là tong(l, m) + tong(m + 1, r)\n\nprint(tong(0, 4))",note:"Với đoạn hai phần tử [0, 1]: m = 0, lời gọi tong(0, −1) là đoạn rỗng mà điều kiện dừng không bắt được; nó sinh tong(0, −2), tong(0, −3)… mãi tới khi Python báo RecursionError. Khi chia, hai nửa phải khác rỗng và nhỏ hơn hẳn: [l, m] và [m + 1, r] với m = (l + r) // 2."},cs:{code:"using System;\n\nclass Program\n{\n    static int[] a = { 3, 1, 4, 1, 5 };\n\n    static int Tong(int l, int r)          // tổng a[l..r]\n    {\n        if (l == r) return a[l];\n        int m = (l + r) / 2;\n        return Tong(l, m - 1) + Tong(m, r);   // sai: phải là Tong(l, m) + Tong(m + 1, r)\n    }\n\n    static void Main()\n    {\n        Console.WriteLine(Tong(0, 4));\n    }\n}",note:"Với đoạn hai phần tử [0, 1]: m = 0, lời gọi Tong(0, −1) là đoạn rỗng mà điều kiện dừng không bắt được, và nó lại sinh Tong(0, −1)… mãi tới khi tràn ngăn xếp. Khi chia, hai nửa phải khác rỗng và nhỏ hơn hẳn: [l, m] và [m + 1, r] với m = (l + r) / 2."}}];
