makeEx2(document.getElementById("ex-l21"),sim21,[{t:"Đoạn con có tổng lớn nhất",d:"Đầu vào: dòng 1 là n (1 ≤ n ≤ 10^5); dòng 2 là n số nguyên a₁ … aₙ (|aᵢ| ≤ 10^9). Đầu ra: tổng lớn nhất của một đoạn liên tiếp khác rỗng.",tests:[{in:"8\n-2 1 -3 4 -1 2 1 -5",out:"6"},{in:"1\n-7",out:"-7"},{in:"5\n-3 -1 -4 -1 -5",out:"-1"},{in:"6\n1000000000 1000000000 -1 1000000000 1000000000 1000000000",out:"4999999999"},{in:"5\n2 -1 2 -1 2",out:"4"}],start:"#include <iostream>\n#include <algorithm>\nusing namespace std;\n\nlong long a[100000];\n\nlong long tot(int l, int r) {\n    // điều kiện dừng: một phần tử\n    // kết quả = max(nửa trái, nửa phải, đoạn cắt qua điểm giữa)\n    return 0;\n}\n\nint main() {\n    int n;\n    cin >> n;\n    for (int i = 0; i < n; i++) cin >> a[i];\n    cout << tot(0, n - 1) << \"\\n\";\n    return 0;\n}",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>((i*7919)%2001)-1000).join(" "),ns:[250,500,1000,2000],need:"nlogn",limit:n=>60*n*Math.log2(n)+200,why:"Thử mọi đoạn là O(n²). Chia để trị: T(n) = 2T(n/2) + O(n) = O(n log n)."},py:{start:"def tot(l, r):\n    # điều kiện dừng: một phần tử\n    # kết quả = max(nửa trái, nửa phải, đoạn cắt qua điểm giữa)\n    return 0\n\nn = int(input())\na = list(map(int, input().split()))\nprint(tot(0, n - 1))",hints:["Đoạn cắt qua điểm giữa m: đi từ m sang trái, giữ tổng lớn nhất trai; đi từ m + 1 sang phải, giữ tổng lớn nhất phai. Đoạn tốt nhất cắt qua giữa có tổng trai + phai.","Khởi tạo trai = a[m], phai = a[m + 1] (không phải 0) vì đoạn phải khác rỗng và mọi số có thể âm.","Độ sâu đệ quy chỉ khoảng log₂ n ≈ 17, không lo giới hạn đệ quy của Python."]},cs:{start:"using System;\n\nclass Program\n{\n    static long[] a;\n\n    static long Tot(int l, int r)\n    {\n        // điều kiện dừng: một phần tử\n        // kết quả = max(nửa trái, nửa phải, đoạn cắt qua điểm giữa)\n        return 0;\n    }\n\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        a = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n        Console.WriteLine(Tot(0, n - 1));\n    }\n}",hints:["Đoạn cắt qua điểm giữa m: đi từ m sang trái, giữ tổng lớn nhất trai; đi từ m + 1 sang phải, giữ tổng lớn nhất phai. Đoạn tốt nhất cắt qua giữa có tổng trai + phai.","Khởi tạo trai = a[m], phai = a[m + 1] (không phải 0) vì đoạn phải khác rỗng và mọi số có thể âm.","Tổng có thể vượt 2·10⁹: dùng long."]}},{t:"Phần tử đa số",d:"Đầu vào: dòng 1 là n (1 ≤ n ≤ 10^5); dòng 2 là n số nguyên dương a₁ … aₙ (≤ 10^9). Đầu ra: giá trị xuất hiện <b>nhiều hơn n/2 lần<\/b> (phần tử đa số), hoặc -1 nếu không có.",tests:[{in:"7\n3 1 3 3 2 3 3",out:"3"},{in:"4\n1 2 1 2",out:"-1"},{in:"1\n9",out:"9"},{in:"5\n5 5 4 4 4",out:"4"},{in:"6\n7 7 7 8 8 8",out:"-1"}],start:"#include <iostream>\nusing namespace std;\n\nint a[100000];\n\n// trả về phần tử đa số của a[l..r], hoặc -1 nếu không có\nint daSo(int l, int r) {\n    // nếu x là đa số của cả đoạn thì x phải là đa số của ít nhất một nửa\n    return -1;\n}\n\nint main() {\n    int n;\n    cin >> n;\n    for (int i = 0; i < n; i++) cin >> a[i];\n    cout << daSo(0, n - 1) << \"\\n\";\n    return 0;\n}",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>i%2==0?7:(i*37)%1000+8).join(" "),ns:[250,500,1000,2000],need:"nlogn",limit:n=>45*n*Math.log2(n)+200,why:"Đếm số lần xuất hiện cho từng phần tử là O(n²). Chia để trị chỉ giữ hai ứng viên mỗi đoạn: O(n log n)."},py:{start:"# trả về phần tử đa số của a[l..r], hoặc -1 nếu không có\ndef daSo(l, r):\n    # nếu x là đa số của cả đoạn thì x phải là đa số của ít nhất một nửa\n    return -1\n\nn = int(input())\na = list(map(int, input().split()))\nprint(daSo(0, n - 1))",hints:["Nếu x xuất hiện nhiều hơn một nửa đoạn thì x cũng xuất hiện nhiều hơn một nửa ở nửa trái hoặc nửa phải.","Vậy chỉ có hai ứng viên: đa số của nửa trái và đa số của nửa phải. Đếm lại từng ứng viên trên cả đoạn trong O(n).","Đừng dùng a.count(x) cho mỗi phần tử: mỗi lần là O(n), tổng O(n²)."]},cs:{start:"using System;\n\nclass Program\n{\n    static int[] a;\n\n    // trả về phần tử đa số của a[l..r], hoặc -1 nếu không có\n    static int DaSo(int l, int r)\n    {\n        // nếu x là đa số của cả đoạn thì x phải là đa số của ít nhất một nửa\n        return -1;\n    }\n\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        Console.WriteLine(DaSo(0, n - 1));\n    }\n}",hints:["Nếu x xuất hiện nhiều hơn một nửa đoạn thì x cũng xuất hiện nhiều hơn một nửa ở nửa trái hoặc nửa phải.","Vậy chỉ có hai ứng viên: đa số của nửa trái và đa số của nửa phải. Đếm lại từng ứng viên trên cả đoạn trong O(n).","T(n) = 2T(n/2) + O(n) = O(n log n)."]}},{t:"Chuỗi ABACABA",d:"Chuỗi S₁ = \"A\"; Sₖ = Sₖ₋₁ + (chữ cái thứ k) + Sₖ₋₁. Ví dụ S₂ = ABA, S₃ = ABACABA, S₄ = ABACABADABACABA. Đầu vào: k và p (1 ≤ k ≤ 26, 1 ≤ p ≤ 2ᵏ − 1). Đầu ra: ký tự thứ p (đếm từ 1) của Sₖ. Chú ý S₂₆ dài hơn 67 triệu ký tự: không dựng chuỗi được.",tests:[{in:"3 4",out:"C"},{in:"1 1",out:"A"},{in:"4 6",out:"B"},{in:"26 33554432",out:"Z"},{in:"26 67108863",out:"A"},{in:"26 50331648",out:"Y"}],start:"#include <iostream>\nusing namespace std;\n\nchar kyTu(int k, long long p) {\n    // Sk = S(k-1) + chữ thứ k + S(k-1); chữ giữa nằm ở vị trí 2^(k-1)\n    return 'A';\n}\n\nint main() {\n    int k;\n    long long p;\n    cin >> k >> p;\n    cout << kyTu(k, p) << \"\\n\";\n    return 0;\n}",py:{start:"def kyTu(k, p):\n    # Sk = S(k-1) + chữ thứ k + S(k-1); chữ giữa nằm ở vị trí 2**(k-1)\n    return \"A\"\n\nk, p = map(int, input().split())\nprint(kyTu(k, p))",hints:["Sₖ dài 2ᵏ − 1; chữ thứ k nằm đúng giữa, ở vị trí 2ᵏ⁻¹. Chữ thứ k là chr(ord(\"A\") + k − 1).","p nhỏ hơn vị trí giữa: tìm tiếp trong Sₖ₋₁ bên trái, vẫn vị trí p. p lớn hơn: tìm trong bản bên phải, ở vị trí p − 2ᵏ⁻¹.","Mỗi lời gọi giảm k đi 1: tối đa 26 lời gọi."]},cs:{start:"using System;\n\nclass Program\n{\n    static char KyTu(int k, long p)\n    {\n        // Sk = S(k-1) + chữ thứ k + S(k-1); chữ giữa nằm ở vị trí 2^(k-1)\n        return 'A';\n    }\n\n    static void Main()\n    {\n        string[] t = Console.ReadLine().Split();\n        int k = int.Parse(t[0]);\n        long p = long.Parse(t[1]);\n        Console.WriteLine(KyTu(k, p));\n    }\n}",hints:["Sₖ dài 2ᵏ − 1; chữ thứ k nằm đúng giữa, ở vị trí 2ᵏ⁻¹ = 1L << (k − 1). Chữ thứ k là (char)('A' + k − 1).","p nhỏ hơn vị trí giữa: tìm tiếp trong Sₖ₋₁ bên trái, vẫn vị trí p. p lớn hơn: tìm trong bản bên phải, ở vị trí p − 2ᵏ⁻¹.","Mỗi lời gọi giảm k đi 1: tối đa 26 lời gọi."]}}]);

